     1→import { useEffect, useMemo, useState } from 'react';
     2→import {
     3→  X,
     4→  RotateCcw,
     5→  Globe,
     6→  ShieldCheck,
     7→  ShieldAlert,
     8→  RefreshCw,
     9→  Loader2,
    10→  SlidersHorizontal,
    11→  Cpu,
    12→  Bell,
    13→  KeyRound,
    14→  ExternalLink,
    15→  BadgeCheck,
    16→  AlertTriangle,
    17→  Unplug,
    18→  Info,
    19→} from 'lucide-react';
    20→import { useTranslation } from 'react-i18next';
    21→import { AnimatePresence, motion } from 'framer-motion';
    22→import { useStore, SubtitleFormat, OutputLanguage } from '@/store/useStore';
    23→import { supportedLanguages } from '@/i18n';
    24→import { CustomSelect, type SelectOption } from '@/components/CustomSelect';
    25→import { getVersion } from '@tauri-apps/api/app';
    26→import { invoke } from '@tauri-apps/api/core';
    27→import { listen } from '@tauri-apps/api/event';
    28→import {
    29→  validatePolarLicense,
    30→  activatePolarLicense,
    31→  deactivatePolarLicense,
    32→  openLicenseCheckout,
    33→  SETTINGS_OPEN_CATEGORY_STORAGE_KEY,
    34→} from '@/lib/license';
    35→import { GlassButton } from '@/components/ui/glass-button';
    36→import { GlassBadge } from '@/components/ui/glass-badge';
    37→import { GlassInput } from '@/components/ui/glass-input';
    38→import { GlassSwitch } from '@/components/ui/glass-switch';
    39→
    40→type SettingsCategory = 'general' | 'output' | 'processing' | 'license' | 'environment' | 'notifications' | 'about';
    41→
    42→const RELEASES_URL = 'https://github.com/0xkamalei/monosub/releases';
    43→
    44→const safeTrim = (value: unknown) => (typeof value === 'string' ? value.trim() : '');
    45→
    46→const isSettingsCategory = (value: string | null): value is SettingsCategory => {
    47→  return value === 'general'
    48→    || value === 'output'
    49→    || value === 'processing'
    50→    || value === 'license'
    51→    || value === 'environment'
    52→    || value === 'notifications'
    53→    || value === 'about';
    54→};
    55→
    56→interface InstallProgressPayload {
    57→  progress: number;
    58→  status: string;
    59→}
    60→
    61→interface GithubReleaseUpdateResult {
    62→  currentVersion: string;
    63→  latestVersion: string;
    64→  latestTag: string;
    65→  releaseName?: string | null;
    66→  releaseUrl: string;
    67→  publishedAt?: string | null;
    68→  hasUpdate: boolean;
    69→}
    70→
    71→export function Settings() {
    72→  const { t, i18n } = useTranslation();
    73→  const [activeCategory, setActiveCategory] = useState<SettingsCategory>('general');
    74→  const isOpen = useStore((state) => state.isSettingsOpen);
    75→  const setIsOpen = useStore((state) => state.setIsSettingsOpen);
    76→  const settings = useStore((state) => state.settings);
    77→  const updateSettings = useStore((state) => state.updateSettings);
    78→  const resetSettings = useStore((state) => state.resetSettings);
    79→  const licenseConfig = useStore((state) => state.licenseConfig);
    80→  const setLicenseKey = useStore((state) => state.setLicenseKey);
    81→  const setLicenseActivationId = useStore((state) => state.setLicenseActivationId);
    82→  const licenseStatus = useStore((state) => state.licenseStatus);
    83→  const licenseMessage = useStore((state) => state.licenseMessage);
    84→  const licenseExpiresAt = useStore((state) => state.licenseExpiresAt);
    85→  const licenseLastCheckedAt = useStore((state) => state.licenseLastCheckedAt);
    86→  const clearLicenseValidation = useStore((state) => state.clearLicenseValidation);
    87→
    88→  const [envStatus, setEnvStatus] = useState<'idle' | 'checking' | 'healthy' | 'broken' | 'error'>('idle');
    89→  const [isRepairing, setIsRepairing] = useState(false);
    90→  const [repairProgress, setRepairProgress] = useState(0);
    91→  const [repairMsg, setRepairMsg] = useState('');
    92→  const [isValidatingLicense, setIsValidatingLicense] = useState(false);
    93→  const [isDeactivatingLicense, setIsDeactivatingLicense] = useState(false);
    94→  const [appVersion, setAppVersion] = useState('');
    95→  const [isCheckingUpdate, setIsCheckingUpdate] = useState(false);
    96→  const [updateResult, setUpdateResult] = useState<GithubReleaseUpdateResult | null>(null);
    97→  const [updateError, setUpdateError] = useState('');
    98→
    99→  useEffect(() => {
   100→    if (!isOpen) {
   101→      return;
   102→    }
   103→
   104→    let initialCategory: SettingsCategory = 'general';
   105→    try {
   106→      const storedCategory = localStorage.getItem(SETTINGS_OPEN_CATEGORY_STORAGE_KEY);
   107→      if (isSettingsCategory(storedCategory)) {
   108→        initialCategory = storedCategory;
   109→      }
   110→      localStorage.removeItem(SETTINGS_OPEN_CATEGORY_STORAGE_KEY);
   111→    } catch (error) {
   112→      console.warn('[Settings] Failed to resolve initial category:', error);
   113→    }
   114→    setActiveCategory(initialCategory);
   115→
   116→    const setupListeners = async () => {
   117→      const unlistenProgress = await listen<InstallProgressPayload>('install_progress', (event) => {
   118→        const { progress, status } = event.payload;
   119→        if (progress > 0) setRepairProgress(progress);
   120→        setRepairMsg(status);
   121→      });
   122→
   123→      const unlistenComplete = await listen('install_complete', () => {
   124→        setIsRepairing(false);
   125→        setEnvStatus('healthy');
   126→        setRepairMsg(t('settings.environment.repairSuccess'));
   127→      });
   128→
   129→      return () => {
   130→        unlistenProgress();
   131→        unlistenComplete();
   132→      };
   133→    };
   134→
   135→    const cleanup = setupListeners();
   136→    checkEnv();
   137→    void getVersion()
   138→      .then((version) => {
   139→        setAppVersion(version);
   140→      })
   141→      .catch((error) => {
   142→        console.error('[getVersion] Failed:', error);
   143→      });
   144→
   145→    return () => {
   146→      cleanup.then((fn) => fn && fn());
   147→    };
   148→  }, [isOpen, t]);
   149→
   150→  const checkEnv = async () => {
   151→    setEnvStatus('checking');
   152→    try {
   153→      const isHealthy = await invoke<boolean>('check_dependencies');
   154→      setEnvStatus(isHealthy ? 'healthy' : 'broken');
   155→    } catch (error) {
   156→      console.error('Failed to check env:', error);
   157→      setEnvStatus('error');
   158→    }
   159→  };
   160→
   161→  const repairEnv = async () => {
   162→    setIsRepairing(true);
   163→    setRepairProgress(0);
   164→    setRepairMsg(t('settings.environment.repairing'));
   165→    try {
   166→      await invoke('install_dependencies');
   167→    } catch (error) {
   168→      console.error('Failed to repair env:', error);
   169→      setIsRepairing(false);
   170→      setRepairMsg(t('settings.environment.repairFailed'));
   171→    }
   172→  };
   173→
   174→  const handleValidateLicense = async () => {
   175→    setIsValidatingLicense(true);
   176→    try {
   177→      if (!safeTrim(licenseConfig?.licenseActivationId)) {
   178→        const activation = await activatePolarLicense();
   179→        if (!activation.activated) {
   180→          return;
   181→        }
   182→      }
   183→      await validatePolarLicense();
   184→    } finally {
   185→      setIsValidatingLicense(false);
   186→    }
   187→  };
   188→
   189→  const handleDeactivateLicense = async () => {
   190→    setIsDeactivatingLicense(true);
   191→    try {
   192→      await deactivatePolarLicense();
   193→    } finally {
   194→      setIsDeactivatingLicense(false);
   195→    }
   196→  };
   197→
   198→  const handleOpenCheckout = async () => {
   199→    await openLicenseCheckout();
   200→  };
   201→
   202→  const handleCheckUpdate = async () => {
   203→    setIsCheckingUpdate(true);
   204→    setUpdateError('');
   205→
   206→    try {
   207→      const result = await invoke<GithubReleaseUpdateResult>('check_github_release_update');
   208→      setUpdateResult(result);
   209→    } catch (error) {
   210→      const message = String(error);
   211→      setUpdateError(message);
   212→      console.error('[check_github_release_update] Failed:', error);
   213→    } finally {
   214→      setIsCheckingUpdate(false);
   215→    }
   216→  };
   217→
   218→  const handleOpenReleasePage = async () => {
   219→    const target = updateResult?.releaseUrl || RELEASES_URL;
   220→    try {
   221→      await invoke('open_external_url', { url: target });
   222→    } catch (error) {
   223→      console.error('[open_external_url] Failed:', error);
   224→      try {
   225→        window.open(target, '_blank');
   226→      } catch (fallbackError) {
   227→        console.error('[window.open] Failed:', fallbackError);
   228→      }
   229→    }
   230→  };
   231→
   232→  const formatOptions: { value: SubtitleFormat; label: string }[] = [
   233→    { value: 'srt', label: 'SRT' },
   234→    { value: 'vtt', label: 'VTT' },
   235→    { value: 'txt', label: 'TXT' },
   236→  ];
   237→
   238→  const languageOptions: SelectOption<OutputLanguage>[] = [
   239→    { value: 'auto', label: t('language.auto') },
   240→    { value: 'en', label: 'English' },
   241→    { value: 'zh', label: '简体中文' },
   242→    { value: 'es', label: 'Español' },
   243→    { value: 'ja', label: '日本語' },
   244→    { value: 'de', label: 'Deutsch' },
   245→    { value: 'fr', label: 'Français' },
   246→    { value: 'pt', label: 'Português' },
   247→    { value: 'zh-tw', label: '繁體中文' },
   248→    { value: 'ko', label: '한국어' },
   249→  ];
   250→
   251→  const uiLanguageOptions = useMemo<SelectOption<string>[]>(() => (
   252→    supportedLanguages.map((lang) => ({
   253→      value: lang.code,
   254→      label: `${lang.flag} ${lang.name}`,
   255→    }))
   256→  ), []);
   257→
   258→  const handleUILanguageChange = (lang: string) => {
   259→    i18n.changeLanguage(lang);
   260→    localStorage.setItem('monosub-language', lang);
   261→  };
   262→
   263→  const currentLang = useMemo(() => {
   264→    const currentLanguage = i18n.language;
   265→    return (
   266→      supportedLanguages.find(
   267→        (lang) => currentLanguage === lang.code || currentLanguage?.startsWith(lang.code.split('-')[0])
   268→      ) || supportedLanguages[1]
   269→    );
   270→  }, [i18n.language]);
   271→  const uiLanguageLabel = t('bottomBar.language').replace(/[:：]\s*$/, '');
   272→  const hasActivationId = safeTrim(licenseConfig?.licenseActivationId).length > 0;
   273→  const isLicenseChecking = isValidatingLicense || licenseStatus === 'checking';
   274→  const hasLicenseChecked = Boolean(licenseLastCheckedAt);
   275→  const normalizedLicenseExpiresAt = safeTrim(licenseExpiresAt);
   276→  const licenseExpiryDisplay = useMemo(() => {
   277→    if (!normalizedLicenseExpiresAt) {
   278→      return '';
   279→    }
   280→
   281→    const expiresAtMs = Date.parse(normalizedLicenseExpiresAt);
   282→    if (Number.isNaN(expiresAtMs)) {
   283→      return normalizedLicenseExpiresAt;
   284→    }
   285→
   286→    return new Intl.DateTimeFormat(i18n.language || undefined, {
   287→      year: 'numeric',
   288→      month: '2-digit',
   289→      day: '2-digit',
   290→      hour: '2-digit',
   291→      minute: '2-digit',
   292→      second: '2-digit',
   293→    }).format(new Date(expiresAtMs));
   294→  }, [i18n.language, normalizedLicenseExpiresAt]);
   295→  const licenseSummary = licenseStatus === 'valid'
   296→    ? t('settings.license.summary.valid')
   297→    : isLicenseChecking
   298→      ? t('settings.license.summary.checking')
   299→      : t('settings.license.summary.notActivated');
   300→  const licenseDetail = licenseStatus === 'valid'
   301→    ? ''
   302→    : (licenseMessage || t('settings.license.summary.hint'));
   303→  const updatePublishedDisplay = useMemo(() => {
   304→    const publishedAt = updateResult?.publishedAt;
   305→    if (!publishedAt) {
   306→      return '';
   307→    }
   308→
   309→    const publishedMs = Date.parse(publishedAt);
   310→    if (Number.isNaN(publishedMs)) {
   311→      return publishedAt;
   312→    }
   313→
   314→    return new Intl.DateTimeFormat(i18n.language || undefined, {
   315→      year: 'numeric',
   316→      month: '2-digit',
   317→      day: '2-digit',
   318→      hour: '2-digit',
   319→      minute: '2-digit',
   320→    }).format(new Date(publishedMs));
   321→  }, [i18n.language, updateResult?.publishedAt]);
   322→
   323→  if (!isOpen) return null;
   324→
   325→  return (
   326→    <div className="fixed inset-0 z-50 flex items-center justify-center">
   327→      <motion.div
   328→        initial={{ opacity: 0 }}
   329→        animate={{ opacity: 1 }}
   330→        exit={{ opacity: 0 }}
   331→        className="absolute inset-0 bg-black/40 dark:bg-black/60 backdrop-blur-xl"
   332→        onClick={() => setIsOpen(false)}
   333→      />
   334→
   335→      <motion.div
   336→        initial={{ opacity: 0, scale: 0.95 }}
   337→        animate={{ opacity: 1, scale: 1 }}
   338→        exit={{ opacity: 0, scale: 0.95 }}
   339→        transition={{ type: 'spring', stiffness: 300, damping: 30 }}
   340→        className="relative glass-medium dark:glass-dark-strong rounded-3xl shadow-glass-lg w-[860px] max-w-[94vw] h-[82vh] max-h-[700px] min-h-[540px] overflow-hidden flex flex-col"
   341→      >
   342→        <div className="flex items-center justify-between px-6 py-4 border-b border-glass-border-light dark:border-glass-border-dark">
   343→          <h2 className="text-lg font-bold text-text-primary dark:text-white">{t('settings.title')}</h2>
   344→          <GlassButton
   345→            variant="ghost"
   346→            size="icon"
   347→            onClick={() => setIsOpen(false)}
   348→            className="h-8 w-8"
   349→          >
   350→            <X className="w-5 h-5 text-text-primary dark:text-gray-300" />
   351→          </GlassButton>
   352→        </div>
   353→
   354→        <div className="flex flex-1 min-h-0 bg-bg-tertiary/85 dark:bg-zinc-900/60">
   355→          <aside className="w-56 border-r border-glass-border-light dark:border-glass-border-dark bg-bg-tertiary/95 dark:bg-zinc-900/80 p-3">
   356→            <div className="space-y-1">
   357→              {[
   358→                { id: 'general' as const, label: uiLanguageLabel, icon: Globe },
   359→                { id: 'output' as const, label: t('settings.output.title'), icon: SlidersHorizontal },
   360→                { id: 'processing' as const, label: t('settings.processing.title'), icon: Cpu },
   361→                { id: 'license' as const, label: t('settings.license.title'), icon: KeyRound },
   362→                { id: 'environment' as const, label: t('settings.environment.title'), icon: RefreshCw },
   363→                { id: 'notifications' as const, label: t('settings.notifications.title'), icon: Bell },
   364→                { id: 'about' as const, label: t('settings.about.title'), icon: Info },
   365→              ].map((item) => {
   366→                const Icon = item.icon;
   367→                const isActive = activeCategory === item.id;
   368→                return (
   369→                  <GlassButton
   370→                    key={item.id}
   371→                    variant={isActive ? 'default' : 'ghost'}
   372→                    size="sm"
   373→                    onClick={() => setActiveCategory(item.id)}
   374→                    className={`w-full justify-start gap-2.5 px-3 h-9 ${isActive
   375→                        ? 'text-text-primary dark:text-white'
   376→                        : 'text-text-secondary dark:text-gray-400 hover:text-text-primary dark:hover:text-white'
   377→                      }`}
   378→                  >
   379→                    <Icon className="w-4 h-4 shrink-0" />
   380→                    <span className="font-medium truncate">{item.label}</span>
   381→                  </GlassButton>
   382→                );
   383→              })}
   384→            </div>
   385→          </aside>
   386→
   387→          <div className="flex-1 min-h-0 flex flex-col bg-bg-tertiary/90 dark:bg-zinc-900/60">
   388→            <div className="px-8 py-5 border-b border-glass-border-light dark:border-glass-border-dark bg-bg-tertiary/95 dark:bg-zinc-900/70">
   389→              <h3 className="text-base font-bold text-text-primary dark:text-white">
   390→                {
   391→                  {
   392→                    general: uiLanguageLabel,
   393→                    output: t('settings.output.title'),
   394→                    processing: t('settings.processing.title'),
   395→                    license: t('settings.license.title'),
   396→                    environment: t('settings.environment.title'),
   397→                    notifications: t('settings.notifications.title'),
   398→                    about: t('settings.about.title'),
   399→                  }[activeCategory]
   400→                }
   401→              </h3>
   402→            </div>
   403→
   404→            <div className="flex-1 min-h-0 overflow-y-auto px-8 py-6 bg-bg-secondary/60 dark:bg-zinc-900/50">
   405→              {activeCategory === 'general' && (
   406→                <section className="space-y-6">
   407→                  <div className="p-4 rounded-2xl border border-divider dark:border-zinc-700 bg-bg-secondary/70 dark:bg-zinc-900/50">
   408→                    <div className="flex items-center justify-between gap-4">
   409→                      <div className="flex items-center gap-2">
   410→                        <Globe className="w-4 h-4 text-text-primary dark:text-gray-300" />
   411→                        <label className="text-sm font-semibold text-text-primary dark:text-gray-200">{uiLanguageLabel}</label>
   412→                      </div>
   413→                      <CustomSelect
   414→                        value={currentLang.code}
   415→                        onChange={handleUILanguageChange}
   416→                        options={uiLanguageOptions}
   417→                        className="w-[260px]"
   418→                      />
   419→                    </div>
   420→                  </div>
   421→                </section>
   422→              )}
   423→
   424→              {activeCategory === 'output' && (
   425→                <section className="space-y-4">
   426→                  <div className="p-4 rounded-2xl border border-divider dark:border-zinc-700 bg-bg-secondary/70 dark:bg-zinc-900/50 space-y-4">
   427→                    <div className="flex items-center justify-between">
   428→                      <label className="text-sm font-semibold text-text-primary dark:text-gray-200">
   429→                        {t('settings.output.format')}
   430→                      </label>
   431→                      <div className="flex gap-1 bg-bg-secondary dark:bg-zinc-800 rounded-lg p-1">
   432→                        {formatOptions.map((opt) => (
   433→                          <GlassButton
   434→                            key={opt.value}
   435→                            variant={settings.outputFormat === opt.value ? 'default' : 'ghost'}
   436→                            size="sm"
   437→                            onClick={() => updateSettings({ outputFormat: opt.value })}
   438→                            className="px-4 h-7 text-sm"
   439→                          >
   440→                            {opt.label}
   441→                          </GlassButton>
   442→                        ))}
   443→                      </div>
   444→                    </div>
   445→
   446→                    <div className="flex items-center justify-between gap-4">
   447→                      <label className="text-sm font-semibold text-text-primary dark:text-gray-200">
   448→                        {t('settings.output.language')}
   449→                      </label>
   450→                      <CustomSelect
