          >
            <RotateCcw className="w-4 h-4" />
            {t('settings.resetDefaults')}
          </GlassButton>
          <GlassButton
            variant="primary"
            size="sm"
            onClick={() => setIsOpen(false)}
          >
            {t('settings.done')}
          </GlassButton>
        </div>
      </motion.div>
    </div>
  );
}

