    65→fn build_endpoints(path: &str) -> Vec<String> {
    66→    let base = POLAR_BASE_URL.trim_end_matches('/');
    67→    let mut endpoints = vec![format!("{}/v1{}", base, path)];
    68→    endpoints.push(format!("{}/api/v1{}", base, path));
    69→    endpoints
    70→}
    71→
    72→fn get_value_by_path<'a>(value: &'a Value, path: &[&str]) -> Option<&'a Value> {
    73→    let mut current = value;
    74→    for segment in path {
    75→        current = current.get(*segment)?;
    76→    }
    77→    Some(current)
    78→}
    79→
    80→fn extract_string(value: &Value, paths: &[&[&str]]) -> Option<String> {
    81→    for path in paths {
    82→        if let Some(v) = get_value_by_path(value, path) {
    83→            if let Some(s) = v.as_str() {
    84→                let trimmed = s.trim();
    85→                if !trimmed.is_empty() {
    86→                    return Some(trimmed.to_string());
    87→                }
    88→            }
    89→        }
    90→    }
    91→    None
    92→}
    93→
    94→fn extract_error_message(body: &Value, fallback: &str) -> String {
    95→    extract_string(
    96→        body,
    97→        &[
    98→            &["detail"],
    99→            &["message"],
   100→            &["error"],
   101→            &["errors", "0", "message"],
   102→        ],
   103→    )
   104→    .unwrap_or_else(|| fallback.to_string())
   105→}
   106→
   107→fn is_activation_required(status: u16, body: &Value) -> bool {
   108→    if status != 422 {
   109→        return false;
   110→    }
   111→
   112→    let msg = extract_error_message(body, "").to_lowercase();
   113→    msg.contains("activation") && msg.contains("required")
   114→}
   115→
   116→async fn post_polar(path: &str, payload: &Value) -> Result<(u16, Value), String> {
   117→    let client = reqwest::Client::builder()
   118→        .timeout(Duration::from_secs(12))
   119→        .build()
   120→        .map_err(|e| format!("Failed to initialize Polar API client: {}", e))?;
   121→
   122→    let endpoints = build_endpoints(path);
   123→    let mut last_error: Option<String> = None;
   124→
   125→    for endpoint in endpoints {
   126→        tracing::info!(endpoint = %endpoint, "Calling Polar API");
   127→        let response = match client.post(&endpoint).json(payload).send().await {
   128→            Ok(resp) => resp,
   129→            Err(err) => {
   130→                tracing::warn!(endpoint = %endpoint, error = %err, "Polar request failed");
   131→                last_error = Some(err.to_string());
   132→                continue;
   133→            }
   134→        };
   135→
   136→        let status_code = response.status().as_u16();
   137→        let body = response.json::<Value>().await.unwrap_or(Value::Null);
   138→
   139→        if status_code == 404 && endpoint.contains("/v1/") && !endpoint.contains("/api/") {
   140→            continue;
   141→        }
   142→
   143→        return Ok((status_code, body));
   144→    }
   145→
   146→    Err(match last_error {
   147→        Some(err) => format!("Unable to reach Polar API: {}", err),
   148→        None => "Unable to reach Polar API.".to_string(),
   149→    })
   150→}
