   164→#[tauri::command]
   165→pub async fn activate_license(
   166→    request: ActivateLicenseRequest,
   167→) -> Result<ActivateLicenseResult, String> {
   168→    validate_fixed_params(&request.organization_id, Some(&request.benefit_id))?;
   169→
   170→    let key = request.key.trim();
   171→    let device_id = request.device_id.trim();
   172→    if key.is_empty() || device_id.is_empty() {
   173→        return Ok(ActivateLicenseResult {
   174→            activated: false,
   175→            activation_id: None,
   176→            status: "invalid".to_string(),
   177→            message: "License key and device ID are required.".to_string(),
   178→            expires_at: None,
   179→        });
   180→    }
   181→
   182→    let payload = json!({
   183→        "key": key,
   184→        "organization_id": POLAR_ORGANIZATION_ID,
   185→        "label": format!("MonoSub-{}", &device_id.chars().take(12).collect::<String>()),
   186→        "meta": {
   187→            "device_id": device_id,
   188→            "client": "monosub-desktop"
   189→        }
   190→    });
   191→
   192→    let (status_code, body) =
   193→        post_polar("/customer-portal/license-keys/activate", &payload).await?;
   194→    if !(200..300).contains(&status_code) {
   195→        let message = extract_error_message(
   196→            &body,
   197→            &format!("License activation failed ({})", status_code),
   198→        );
   199→        return Ok(ActivateLicenseResult {
   200→            activated: false,
   201→            activation_id: None,
   202→            status: "invalid".to_string(),
   203→            message,
   204→            expires_at: extract_string(&body, &[&["license_key", "expires_at"], &["expires_at"]]),
   205→        });
   206→    }
   207→
   208→    let activation_id = extract_string(
   209→        &body,
   210→        &[
   211→            &["id"],
   212→            &["activation_id"],
   213→            &["license_key_activation", "id"],
   214→        ],
   215→    );
   216→
   217→    if activation_id.is_none() {
   218→        return Ok(ActivateLicenseResult {
   219→            activated: false,
   220→            activation_id: None,
   221→            status: "error".to_string(),
   222→            message: "License activation succeeded but activation ID was missing.".to_string(),
   223→            expires_at: extract_string(&body, &[&["license_key", "expires_at"], &["expires_at"]]),
   224→        });
   225→    }
   226→
   227→    Ok(ActivateLicenseResult {
   228→        activated: true,
   229→        activation_id,
   230→        status: "activated".to_string(),
   231→        message: "License activated on this device.".to_string(),
   232→        expires_at: extract_string(&body, &[&["license_key", "expires_at"], &["expires_at"]]),
   233→    })
   234→}
