   236→#[tauri::command]
   237→pub async fn validate_license(
   238→    request: ValidateLicenseRequest,
   239→) -> Result<ValidateLicenseResult, String> {
   240→    validate_fixed_params(&request.organization_id, Some(&request.benefit_id))?;
   241→
   242→    let key = request.key.trim();
   243→    let device_id = request.device_id.trim();
   244→    if key.is_empty() || device_id.is_empty() {
   245→        return Ok(ValidateLicenseResult {
   246→            valid: false,
   247→            status: "invalid".to_string(),
   248→            message: "License key and device ID are required.".to_string(),
   249→            expires_at: None,
   250→            activation_required: false,
   251→        });
   252→    }
   253→
   254→    let activation_id = request
   255→        .activation_id
   256→        .as_ref()
   257→        .map(|s| s.trim().to_string())
   258→        .filter(|s| !s.is_empty());
   259→
   260→    let mut payload = json!({
   261→        "key": key,
   262→        "organization_id": POLAR_ORGANIZATION_ID,
   263→        "benefit_id": POLAR_BENEFIT_ID,
   264→        "conditions": {
   265→            "device_id": device_id
   266→        }
   267→    });
   268→
   269→    if let Some(activation_id) = activation_id {
   270→        payload["activation_id"] = Value::String(activation_id);
   271→    }
   272→
   273→    let (status_code, body) =
   274→        post_polar("/customer-portal/license-keys/validate", &payload).await?;
   275→    if !(200..300).contains(&status_code) {
   276→        let activation_required = is_activation_required(status_code, &body);
   277→        return Ok(ValidateLicenseResult {
   278→            valid: false,
   279→            status: if activation_required {
   280→                "activation_required".to_string()
   281→            } else {
   282→                "invalid".to_string()
   283→            },
   284→            message: extract_error_message(
   285→                &body,
   286→                &format!("License validation failed ({})", status_code),
   287→            ),
   288→            expires_at: extract_string(&body, &[&["license_key", "expires_at"], &["expires_at"]]),
   289→            activation_required,
   290→        });
   291→    }
   292→
   293→    let status = extract_string(&body, &[&["status"], &["license_key", "status"]])
   294→        .unwrap_or_else(|| "unknown".to_string());
   295→    let normalized_status = status.to_lowercase();
   296→    let valid = normalized_status == "granted" || normalized_status == "active";
   297→
   298→    Ok(ValidateLicenseResult {
   299→        valid,
   300→        status: status.clone(),
   301→        message: if valid {
   302→            "License is valid.".to_string()
   303→        } else {
   304→            format!("License status is \"{}\".", status)
   305→        },
   306→        expires_at: extract_string(&body, &[&["license_key", "expires_at"], &["expires_at"]]),
   307→        activation_required: false,
   308→    })
   309→}
