    49→/// Check if running in development mode
    50→fn is_dev_mode() -> bool {
    51→    // 检查是否存在 core-engine/.venv 目录
    52→    let current_dir = std::env::current_dir().ok();
    53→    if let Some(dir) = current_dir {
    54→        // Dev: monosub/src-tauri -> monosub/core-engine/.venv
    55→        if dir.join("../core-engine/.venv").exists() {
    56→            return true;
    57→        }
    58→    }
    59→    false
    60→}
