    62→/// Get the core-engine directory
    63→fn get_core_engine_dir(app: &AppHandle) -> Result<std::path::PathBuf, String> {
    64→    use tauri::Manager;
    65→    if is_dev_mode() {
    66→        let current_dir = std::env::current_dir().map_err(|e| e.to_string())?;
    67→        Ok(current_dir.join("../core-engine"))
    68→    } else {
    69→        let resource_dir = app.path().resource_dir().map_err(|e| e.to_string())?;
    70→        Ok(resource_dir.join("resources").join("core-engine"))
    71→    }
    72→}
