    74→fn is_audio_input(path: &Path) -> bool {
    75→    path.extension()
    76→        .and_then(|ext| ext.to_str())
    77→        .map(|ext| {
    78→            ["mp3", "wav", "flac", "aac", "m4a", "ogg", "wma"]
    79→                .contains(&ext.to_lowercase().as_str())
    80→        })
    81→        .unwrap_or(false)
    82→}
    83→
    84→fn get_audio_cache_path(video_path: &Path) -> Option<PathBuf> {
    85→    let parent = video_path.parent()?;
    86→    let stem = video_path.file_stem()?.to_str()?;
    87→    Some(parent.join(format!(".{}_audio.wav", stem)))
    88→}
    89→
    90→fn is_cache_fresh(cache_path: &Path, source_path: &Path) -> bool {
    91→    let cache_meta = match std::fs::metadata(cache_path) {
    92→        Ok(meta) => meta,
    93→        Err(_) => return false,
    94→    };
    95→    let source_meta = match std::fs::metadata(source_path) {
    96→        Ok(meta) => meta,
    97→        Err(_) => return false,
    98→    };
    99→
   100→    let cache_mtime = match cache_meta.modified() {
   101→        Ok(time) => time,
   102→        Err(_) => return false,
   103→    };
   104→    let source_mtime = match source_meta.modified() {
   105→        Ok(time) => time,
   106→        Err(_) => return false,
   107→    };
   108→
   109→    cache_mtime >= source_mtime
   110→}
