   112→/// Start transcription task using Tauri sidecar
   113→#[tauri::command]
   114→pub async fn start_transcription(
   115→    app: AppHandle,
   116→    request: TranscribeRequest,
   117→) -> Result<String, String> {
   118→    let task_id = request.id.clone();
   119→    let video_path = request.path.clone();
   120→    let output_path = request.output_path.clone();
   121→    let format = request.format.unwrap_or_else(|| "srt".to_string());
   122→    let language = request.language.unwrap_or_else(|| "zh".to_string());
   123→    let requested_device = request.device.unwrap_or_else(|| "auto".to_string());
   124→    let requested_device = requested_device.trim().to_lowercase();
   125→    let device = match requested_device.as_str() {
   126→        "cpu" | "cuda" | "mps" | "auto" => requested_device,
   127→        _ => "auto".to_string(),
   128→    };
   129→    let enable_diarization = request.enable_diarization.unwrap_or(false);
   130→
   131→    tracing::info!(
   132→        task_id = %task_id,
   133→        video_path = %video_path,
   134→        output_path = %output_path,
   135→        format = %format,
   136→        language = %language,
   137→        device = %device,
   138→        enable_diarization = %enable_diarization,
   139→        "Starting transcription task"
   140→    );
   141→
   142→    // Check if task already exists
   143→    let tasks = TASKS.lock().await;
   144→    if tasks.contains_key(&task_id) {
   145→        tracing::warn!(task_id = %task_id, "Task already running");
   146→        return Err("Task already running".to_string());
   147→    }
   148→    drop(tasks);
   149→
   150→    let task_id_for_map = task_id.clone();
   151→    let task_id_for_spawn = task_id.clone();
   152→
   153→    // Spawn async task for transcription
   154→    let handle = tokio::spawn(async move {
   155→        let task_id = task_id_for_spawn;
   156→
   157→        // Emit initial progress
   158→        let _ = app.emit(
   159→            "transcribe_progress",
   160→            TranscribeProgress {
   161→                task_id: task_id.clone(),
   162→                progress: 0.0,
   163→                status: "Pending in queue...".to_string(),
   164→                step: None,
   165→                total_time: None,
   166→            },
   167→        );
   168→
   169→        let input_path = Path::new(&video_path);
   170→        let is_audio = is_audio_input(input_path);
   171→
   172→        let (final_audio_path, keep_audio_cache) = if !is_audio {
   173→            // Wait for audio extraction permit
   174→            let _permit = AUDIO_SEMAPHORE.acquire().await;
   175→
   176→            let _ = app.emit(
   177→                "transcribe_progress",
   178→                TranscribeProgress {
   179→                    task_id: task_id.clone(),
   180→                    progress: 0.0,
   181→                    status: "Extracting audio...".to_string(),
   182→                    step: Some(StepInfo {
   183→                        current_step: 1,
   184→                        total_steps: 4,
   185→                        step_name: "Extracting audio".to_string(),
   186→                        step_elapsed: 0.0,
   187→                        total_elapsed: 0.0,
   188→                    }),
   189→                    total_time: None,
   190→                },
   191→            );
   192→
   193→            let cache_path = get_audio_cache_path(input_path).unwrap_or_else(|| {
   194→                std::env::temp_dir().join(format!("extracted_{}.wav", uuid::Uuid::new_v4()))
   195→            });
   196→            let keep_cache = cache_path
   197→                .parent()
   198→                .map(|parent| parent != std::env::temp_dir())
   199→                .unwrap_or(false);
   200→
   201→            if is_cache_fresh(&cache_path, input_path) {
   202→                let cache_path_str = cache_path.to_string_lossy().to_string();
   203→                tracing::info!(
   204→                    task_id = %task_id,
   205→                    cached_audio = %cache_path_str,
   206→                    "Using cached extracted audio"
   207→                );
   208→                (cache_path_str, keep_cache)
   209→            } else {
   210→                let audio_path_str = cache_path.to_string_lossy().to_string();
   211→                let ffmpeg_path = crate::commands::video::get_ffmpeg_path_for_python(Some(&app));
   212→                let output = tokio::process::Command::new(&ffmpeg_path)
   213→                    .args(&[
   214→                        "-i",
   215→                        &video_path,
   216→                        "-vn",
   217→                        "-acodec",
   218→                        "pcm_s16le",
   219→                        "-ar",
   220→                        "16000",
   221→                        "-ac",
   222→                        "1",
   223→                        "-y",
   224→                        &audio_path_str,
   225→                    ])
   226→                    .output()
   227→                    .await;
   228→
   229→                match output {
   230→                    Ok(out) if out.status.success() => {
   231→                        tracing::info!(
   232→                            task_id = %task_id,
   233→                            cached_audio = %audio_path_str,
   234→                            "Audio extracted successfully"
   235→                        );
   236→                        (audio_path_str, keep_cache)
   237→                    }
   238→                    _ => {
   239→                        let _ = std::fs::remove_file(&cache_path);
   240→                        tracing::error!(task_id = %task_id, "Failed to extract audio natively, falling back to python extraction");
   241→                        (video_path.clone(), false)
   242→                    }
   243→                }
   244→            }
   245→        } else {
   246→            (video_path.clone(), false)
   247→        };
   248→
   249→        // Wait for transcription permit
   250→        let _permit = TRANSCRIBE_SEMAPHORE.acquire().await;
   251→
   252→        let _ = app.emit(
   253→            "transcribe_progress",
   254→            TranscribeProgress {
   255→                task_id: task_id.clone(),
   256→                progress: 0.0,
   257→                status: "Starting transcription...".to_string(),
   258→                step: Some(StepInfo {
   259→                    current_step: 2,
   260→                    total_steps: 4,
   261→                    step_name: "Loading model".to_string(),
   262→                    step_elapsed: 0.0,
   263→                    total_elapsed: 0.0,
   264→                }),
   265→                total_time: None,
   266→            },
   267→        );
   268→
   269→        // 开发模式：使用 Python 直接运行
   270→        // 生产模式：使用 sidecar 运行打包的可执行文件
   271→        let is_dev = is_dev_mode();
   272→        tracing::info!(task_id = %task_id, is_dev_mode = is_dev, "Running transcription");
   273→
   274→        let result = if is_dev {
   275→            run_dev_mode(
   276→                &app,
   277→                &task_id,
   278→                &final_audio_path,
   279→                &output_path,
   280→                &format,
   281→                &language,
   282→                &device,
   283→                enable_diarization,
   284→            )
   285→            .await
   286→        } else {
   287→            run_sidecar(
   288→                &app,
   289→                &task_id,
   290→                &final_audio_path,
   291→                &output_path,
   292→                &format,
   293→                &language,
   294→                &device,
   295→                enable_diarization,
   296→            )
   297→            .await
   298→        };
   299→
   300→        // Cleanup temporary audio file if we created one (keep media-directory cache)
   301→        if final_audio_path != video_path && !keep_audio_cache {
   302→            let _ = std::fs::remove_file(&final_audio_path);
   303→        }
   304→
   305→        if let Err(e) = result {
   306→            tracing::error!(task_id = %task_id, error = %e, "Transcription failed");
   307→            // 发送错误事件（不是 progress 事件）
   308→            let _ = app.emit(
   309→                "transcribe_error",
   310→                TranscribeProgress {
   311→                    task_id: task_id.clone(),
   312→                    progress: 0.0,
   313→                    status: format!("Error: {}", e),
   314→                    step: None,
   315→                    total_time: None,
   316→                },
   317→            );
   318→        } else {
   319→            tracing::info!(task_id = %task_id, "Transcription completed successfully");
   320→        }
   321→
   322→        // Remove task from map
   323→        TASKS.lock().await.remove(&task_id);
   324→    });
   325→
   326→    // Store task handle
   327→    TASKS.lock().await.insert(task_id_for_map, handle);
   328→
   329→    Ok(task_id)
   330→}
