   332→/// Run in production mode using sidecar
   333→async fn run_sidecar(
   334→    app: &AppHandle,
   335→    task_id: &str,
   336→    video_path: &str,
   337→    output_path: &str,
   338→    format: &str,
   339→    language: &str,
   340→    device: &str,
   341→    enable_diarization: bool,
   342→) -> Result<(), String> {
   343→    tracing::info!(task_id = %task_id, "Starting sidecar process");
   344→    let shell = app.shell();
   345→
   346→    // Get ffmpeg path from video.rs helper
   347→    let ffmpeg_path = crate::commands::video::get_ffmpeg_path_for_python(Some(app));
   348→    let ffprobe_path = crate::commands::video::get_ffprobe_path_for_python(Some(app));
   349→
   350→    tracing::debug!(
   351→        task_id = %task_id,
   352→        ffmpeg_path = %ffmpeg_path,
   353→        ffprobe_path = %ffprobe_path,
   354→        "Setting ffmpeg paths for sidecar subprocess"
   355→    );
   356→
   357→    // 使用 sidecar 运行 monosub-engine
   358→    let sidecar_command = shell.sidecar("monosub-engine").map_err(|e| {
   359→        tracing::error!(task_id = %task_id, error = %e, "Failed to create sidecar command");
   360→        format!("Failed to create sidecar command: {}", e)
   361→    })?;
   362→
   363→    // 构建命令参数
   364→    let mut args = vec![
   365→        video_path.to_string(),
   366→        output_path.to_string(),
   367→        "--format".to_string(),
   368→        format.to_string(),
   369→        "--language".to_string(),
   370→        language.to_string(),
   371→        "--device".to_string(),
   372→        device.to_string(),
   373→    ];
   374→
   375→    // 如果启用了说话人分离，添加参数
   376→    if enable_diarization {
   377→        args.push("--diarization".to_string());
   378→        tracing::info!(task_id = %task_id, "Speaker diarization enabled");
   379→    }
   380→
   381→    let (mut rx, _child) = sidecar_command
   382→        .args(&args)
   383→        .env("MONOSUB_FFMPEG_PATH", ffmpeg_path)
   384→        .env("MONOSUB_FFPROBE_PATH", ffprobe_path)
   385→        .env("MONOSUB_ASR_DEVICE", device)
   386→        .spawn()
   387→        .map_err(|e| {
   388→            tracing::error!(task_id = %task_id, error = %e, "Failed to spawn sidecar");
   389→            format!("Failed to spawn sidecar: {}", e)
   390→        })?;
   391→
   392→    tracing::debug!(task_id = %task_id, "Sidecar process spawned successfully");
   393→
   394→    // Read output
   395→    while let Some(event) = rx.recv().await {
   396→        match event {
   397→            tauri_plugin_shell::process::CommandEvent::Stdout(line) => {
   398→                let line_str = String::from_utf8_lossy(&line);
   399→                process_output_line(app, task_id, &line_str);
   400→            }
   401→            tauri_plugin_shell::process::CommandEvent::Stderr(line) => {
   402→                let line_str = String::from_utf8_lossy(&line);
   403→                tracing::warn!(task_id = %task_id, stderr = %line_str, "Sidecar stderr output");
   404→
   405→                // 如果是 Python 错误（ModuleNotFoundError, ImportError 等），发送错误事件
   406→                if line_str.contains("Error") || line_str.contains("Traceback") {
   407→                    let _ = app.emit(
   408→                        "transcribe_error",
   409→                        TranscribeProgress {
   410→                            task_id: task_id.to_string(),
   411→                            progress: 0.0,
   412→                            status: format!("Python Error: {}", line_str.trim()),
   413→                            step: None,
   414→                            total_time: None,
   415→                        },
   416→                    );
   417→                }
   418→            }
   419→            tauri_plugin_shell::process::CommandEvent::Error(err) => {
   420→                tracing::error!(task_id = %task_id, error = %err, "Sidecar process error");
   421→                return Err(format!("Process error: {}", err));
   422→            }
   423→            tauri_plugin_shell::process::CommandEvent::Terminated(payload) => {
   424→                tracing::info!(task_id = %task_id, exit_code = ?payload.code, "Sidecar process terminated");
   425→                if payload.code != Some(0) {
   426→                    let error_msg = format!("Process exited with code: {:?}", payload.code);
   427→                    let _ = app.emit(
   428→                        "transcribe_error",
   429→                        TranscribeProgress {
   430→                            task_id: task_id.to_string(),
   431→                            progress: 0.0,
   432→                            status: error_msg.clone(),
   433→                            step: None,
   434→                            total_time: None,
   435→                        },
   436→                    );
   437→                    return Err(error_msg);
   438→                }
   439→            }
   440→            _ => {}
   441→        }
   442→    }
   443→
   444→    Ok(())
   445→}
