   447→/// Run in development mode using Python directly
   448→async fn run_dev_mode(
   449→    app: &AppHandle,
   450→    task_id: &str,
   451→    video_path: &str,
   452→    output_path: &str,
   453→    format: &str,
   454→    language: &str,
   455→    device: &str,
   456→    enable_diarization: bool,
   457→) -> Result<(), String> {
   458→    use tokio::io::{AsyncBufReadExt, BufReader};
   459→    use tokio::process::Command;
   460→
   461→    tracing::info!(task_id = %task_id, "Starting development mode with Python venv");
   462→
   463→    // 获取 Python 路径
   464→    let current_dir = std::env::current_dir().map_err(|e| e.to_string())?;
   465→    let parent = current_dir.parent().ok_or("No parent directory")?;
   466→    let venv_python = parent.join("core-engine/.venv/bin/python");
   467→    let main_py = parent.join("core-engine/main.py");
   468→
   469→    if !venv_python.exists() || !main_py.exists() {
   470→        tracing::error!(
   471→            task_id = %task_id,
   472→            venv_python = ?venv_python,
   473→            main_py = ?main_py,
   474→            "Development environment not found"
   475→        );
   476→        return Err("Development environment not found".to_string());
   477→    }
   478→
   479→    tracing::debug!(
   480→        task_id = %task_id,
   481→        venv_python = ?venv_python,
   482→        main_py = ?main_py,
   483→        "Using Python venv"
   484→    );
   485→
   486→    let cmd_str = format!(
   487→        "{} {} {} {} --format {} --language {} --device {}",
   488→        venv_python.display(),
   489→        main_py.display(),
   490→        video_path,
   491→        output_path,
   492→        format,
   493→        language,
   494→        device
   495→    );
   496→
   497→    tracing::info!(task_id = %task_id, command = %cmd_str, "Executing Python command");
   498→
   499→    let _ = app.emit(
   500→        "transcribe_progress",
   501→        TranscribeProgress {
   502→            task_id: task_id.to_string(),
   503→            progress: 0.0,
   504→            status: format!("CMD: {}", cmd_str),
   505→            step: None,
   506→            total_time: None,
   507→        },
   508→    );
   509→
   510→    // Get ffmpeg path from video.rs helper
   511→    let ffmpeg_path = crate::commands::video::get_ffmpeg_path_for_python(Some(app));
   512→    let ffprobe_path = crate::commands::video::get_ffprobe_path_for_python(Some(app));
   513→
   514→    tracing::debug!(
   515→        task_id = %task_id,
   516→        ffmpeg_path = %ffmpeg_path,
   517→        ffprobe_path = %ffprobe_path,
   518→        "Setting ffmpeg paths for Python subprocess"
   519→    );
   520→
   521→    // 构建命令
   522→    let mut command = Command::new(&venv_python);
   523→    command
   524→        .arg(&main_py)
   525→        .arg(video_path)
   526→        .arg(output_path)
   527→        .arg("--format")
   528→        .arg(format)
   529→        .arg("--language")
   530→        .arg(language)
   531→        .arg("--device")
   532→        .arg(device);
   533→
   534→    // 如果启用了说话人分离，添加参数
   535→    if enable_diarization {
   536→        command.arg("--diarization");
   537→        tracing::info!(task_id = %task_id, "Speaker diarization enabled (dev mode)");
   538→    }
   539→
   540→    let mut child = command
   541→        .env("MONOSUB_FFMPEG_PATH", ffmpeg_path)
   542→        .env("MONOSUB_FFPROBE_PATH", ffprobe_path)
   543→        .env("MONOSUB_ASR_DEVICE", device)
   544→        .stdout(std::process::Stdio::piped())
   545→        .stderr(std::process::Stdio::piped())
   546→        .spawn()
   547→        .map_err(|e| {
   548→            tracing::error!(task_id = %task_id, error = %e, "Failed to spawn Python process");
   549→            format!("Failed to spawn process: {}", e)
   550→        })?;
   551→
   552→    tracing::debug!(task_id = %task_id, "Python process spawned successfully");
   553→
   554→    let stdout = child.stdout.take().ok_or("Failed to capture stdout")?;
   555→    let stderr = child.stderr.take().ok_or("Failed to capture stderr")?;
   556→
   557→    let mut stdout_reader = BufReader::new(stdout).lines();
   558→    let mut stderr_reader = BufReader::new(stderr).lines();
   559→
   560→    // Read stderr in background
   561→    let app_clone = app.clone();
   562→    let task_id_clone = task_id.to_string();
   563→    tokio::spawn(async move {
   564→        while let Ok(Some(line)) = stderr_reader.next_line().await {
   565→            tracing::warn!(task_id = %task_id_clone, stderr = %line, "Python stderr output");
   566→
   567→            // 如果是 Python 错误，发送错误事件
   568→            if line.contains("Error") || line.contains("Traceback") {
   569→                let _ = app_clone.emit(
   570→                    "transcribe_error",
   571→                    TranscribeProgress {
   572→                        task_id: task_id_clone.clone(),
   573→                        progress: 0.0,
   574→                        status: format!("Python Error: {}", line.trim()),
   575→                        step: None,
   576→                        total_time: None,
   577→                    },
   578→                );
   579→            }
   580→        }
   581→    });
   582→
   583→    // Read stdout
   584→    while let Ok(Some(line)) = stdout_reader.next_line().await {
   585→        tracing::debug!(task_id = %task_id, stdout = %line, "Python stdout output");
   586→        process_output_line(app, task_id, &line);
   587→    }
   588→
   589→    // Wait for process to complete
   590→    let status = child.wait().await.map_err(|e| {
   591→        tracing::error!(task_id = %task_id, error = %e, "Error waiting for Python process");
   592→        format!("Wait error: {}", e)
   593→    })?;
   594→
   595→    tracing::info!(task_id = %task_id, exit_code = ?status.code(), "Python process exited");
   596→
   597→    if !status.success() {
   598→        tracing::error!(task_id = %task_id, exit_code = ?status.code(), "Python process failed");
   599→        let error_msg = format!("Process exited with code: {:?}", status.code());
   600→        let _ = app.emit(
   601→            "transcribe_error",
   602→            TranscribeProgress {
   603→                task_id: task_id.to_string(),
   604→                progress: 0.0,
   605→                status: error_msg.clone(),
   606→                step: None,
   607→                total_time: None,
   608→            },
   609→        );
   610→        return Err(error_msg);
   611→    }
   612→
   613→    Ok(())
   614→}
