   616→// Thread-local storage for current step info
   617→thread_local! {
   618→    static CURRENT_STEP: std::cell::RefCell<Option<StepInfo>> = std::cell::RefCell::new(None);
   619→    static TOTAL_TIME: std::cell::RefCell<Option<f64>> = std::cell::RefCell::new(None);
   620→}
   621→
   622→/// Process output line from Python script
   623→fn process_output_line(app: &AppHandle, task_id: &str, line: &str) {
   624→    if line.starts_with("STEP:") {
   625→        // Format: STEP:1/4:step_name
   626→        let parts: Vec<&str> = line[5..].splitn(3, ':').collect();
   627→        if parts.len() >= 2 {
   628→            let step_parts: Vec<&str> = parts[0].split('/').collect();
   629→            if step_parts.len() == 2 {
   630→                if let (Ok(current), Ok(total)) =
   631→                    (step_parts[0].parse::<u32>(), step_parts[1].parse::<u32>())
   632→                {
   633→                    let step_name = if parts.len() >= 2 {
   634→                        parts[1].to_string()
   635→                    } else {
   636→                        "Processing".to_string()
   637→                    };
   638→
   639→                    let step_info = StepInfo {
   640→                        current_step: current,
   641→                        total_steps: total,
   642→                        step_name: step_name.clone(),
   643→                        step_elapsed: 0.0,
   644→                        total_elapsed: 0.0,
   645→                    };
   646→
   647→                    CURRENT_STEP.with(|s| {
   648→                        *s.borrow_mut() = Some(step_info.clone());
   649→                    });
   650→
   651→                    tracing::info!(task_id = %task_id, step = current, total = total, name = %step_name, "Step started");
   652→
   653→                    let _ = app.emit(
   654→                        "transcribe_progress",
   655→                        TranscribeProgress {
   656→                            task_id: task_id.to_string(),
   657→                            progress: 0.0,
   658→                            status: step_name,
   659→                            step: Some(step_info),
   660→                            total_time: None,
   661→                        },
   662→                    );
   663→                }
   664→            }
   665→        }
   666→    } else if line.starts_with("ELAPSED:") {
   667→        // Format: ELAPSED:12.5 (total elapsed seconds)
   668→        if let Ok(elapsed) = line[8..].trim().parse::<f64>() {
   669→            CURRENT_STEP.with(|s| {
   670→                if let Some(ref mut step) = *s.borrow_mut() {
   671→                    step.total_elapsed = elapsed;
   672→
   673→                    let _ = app.emit(
   674→                        "transcribe_progress",
   675→                        TranscribeProgress {
   676→                            task_id: task_id.to_string(),
   677→                            progress: 0.0,
   678→                            status: step.step_name.clone(),
   679→                            step: Some(step.clone()),
   680→                            total_time: None,
   681→                        },
   682→                    );
   683→                }
   684→            });
   685→        }
   686→    } else if line.starts_with("STEP_ELAPSED:") {
   687→        // Format: STEP_ELAPSED:3.2 (step elapsed seconds)
   688→        if let Ok(step_elapsed) = line[13..].trim().parse::<f64>() {
   689→            CURRENT_STEP.with(|s| {
   690→                if let Some(ref mut step) = *s.borrow_mut() {
   691→                    step.step_elapsed = step_elapsed;
   692→                }
   693→            });
   694→        }
   695→    } else if line.starts_with("TOTAL_TIME:") {
   696→        // Format: TOTAL_TIME:45.3
   697→        if let Ok(total) = line[11..].trim().parse::<f64>() {
   698→            TOTAL_TIME.with(|t| {
   699→                *t.borrow_mut() = Some(total);
   700→            });
   701→            tracing::info!(task_id = %task_id, total_time = total, "Total processing time");
   702→        }
   703→    } else if line.starts_with("PROGRESS:") {
   704→        // Legacy support - ignore PROGRESS messages now
   705→        tracing::debug!(task_id = %task_id, line = %line, "Ignoring legacy PROGRESS message");
   706→    } else if line.starts_with("MSG:") {
   707→        let message = &line[4..];
   708→        tracing::info!(task_id = %task_id, message = %message, "Transcription message");
   709→
   710→        let current_step = CURRENT_STEP.with(|s| s.borrow().clone());
   711→
   712→        let _ = app.emit(
   713→            "transcribe_progress",
   714→            TranscribeProgress {
   715→                task_id: task_id.to_string(),
   716→                progress: 0.0,
   717→                status: message.to_string(),
   718→                step: current_step,
   719→                total_time: None,
   720→            },
   721→        );
   722→    } else if line.starts_with("SUCCESS:") {
   723→        let output_file = &line[8..];
   724→        tracing::info!(task_id = %task_id, output_file = %output_file, "Transcription completed");
   725→
   726→        let total_time = TOTAL_TIME.with(|t| *t.borrow());
   727→
   728→        let _ = app.emit(
   729→            "transcribe_complete",
   730→            TranscribeProgress {
   731→                task_id: task_id.to_string(),
   732→                progress: 100.0,
   733→                status: format!("Completed: {}", output_file),
   734→                step: None,
   735→                total_time,
   736→            },
   737→        );
   738→
   739→        // Clear thread-local state
   740→        CURRENT_STEP.with(|s| *s.borrow_mut() = None);
   741→        TOTAL_TIME.with(|t| *t.borrow_mut() = None);
   742→    } else if line.starts_with("ERROR:") {
   743→        let error_msg = &line[6..];
   744→        tracing::error!(task_id = %task_id, error = %error_msg, "Transcription error");
   745→        // Python 脚本中的 ERROR: 消息，发送到 transcribe_error 事件
   746→        let _ = app.emit(
   747→            "transcribe_error",
   748→            TranscribeProgress {
   749→                task_id: task_id.to_string(),
   750→                progress: 0.0,
   751→                status: format!("Error: {}", error_msg),
   752→                step: None,
   753→                total_time: None,
   754→            },
   755→        );
   756→
   757→        // Clear thread-local state
   758→        CURRENT_STEP.with(|s| *s.borrow_mut() = None);
   759→        TOTAL_TIME.with(|t| *t.borrow_mut() = None);
   760→    }
   761→}
