   763→/// Cancel transcription task
   764→#[tauri::command]
   765→pub async fn cancel_transcription(task_id: String) -> Result<(), String> {
   766→    tracing::info!(task_id = %task_id, "Cancelling transcription task");
   767→    let mut tasks = TASKS.lock().await;
   768→
   769→    if let Some(handle) = tasks.remove(&task_id) {
   770→        handle.abort();
   771→        tracing::info!(task_id = %task_id, "Transcription task cancelled successfully");
   772→        Ok(())
   773→    } else {
   774→        tracing::warn!(task_id = %task_id, "Cannot cancel: task not found");
   775→        Err("Task not found".to_string())
   776→    }
   777→}
