   779→/// Check if AI dependencies are correctly installed
   780→#[tauri::command]
   781→pub async fn check_dependencies(app: AppHandle) -> Result<bool, String> {
   782→    tracing::info!("Checking AI dependencies...");
   783→    let is_dev = is_dev_mode();
   784→
   785→    if is_dev {
   786→        let core_dir = get_core_engine_dir(&app)?;
   787→        let venv_python = core_dir.join(".venv/bin/python");
   788→        if !venv_python.exists() {
   789→            return Ok(false);
   790→        }
   791→
   792→        let output = tokio::process::Command::new(&venv_python)
   793→            .arg("-c")
   794→            .arg("import funasr; print('OK')")
   795→            .output()
   796→            .await
   797→            .map_err(|e| e.to_string())?;
   798→
   799→        return Ok(output.status.success());
   800→    } else {
   801→        // sidecar mode
   802→        use tauri_plugin_shell::ShellExt;
   803→        let shell = app.shell();
   804→        let sidecar_command = shell
   805→            .sidecar("monosub-engine")
   806→            .map_err(|e| format!("Sidecar error: {}", e))?;
   807→
   808→        // We run with --help to check if it can start and import everything
   809→        let output = sidecar_command
   810→            .arg("--help")
   811→            .output()
   812→            .await
   813→            .map_err(|e| format!("Failed to run sidecar: {}", e))?;
   814→
