name = "monosub"
version = "1.1.30"
description = "Local voice to article desktop app"
authors = ["VoiceToText"]
edition = "2021"

[build-dependencies]
tauri-build = { version = "2", features = [] }

[dependencies]
tauri = { version = "2", features = ["macos-private-api", "tray-icon"] }
window-vibrancy = "0.6"
