const POLAR_BENEFIT_ID: &str = "f288c189-f31b-4e0a-b849-1a0308420110";
const LICENSE_HMAC_KEY: &[u8] = b"ms_lic_v1_7f3a9c2e5b8d4f1a6e0c3b9d2f5a8e1c";

