  try {
    localStorage.setItem(SETTINGS_OPEN_CATEGORY_STORAGE_KEY, 'license');
  } catch (error) {
    console.warn('[openLicenseSettings] Failed to persist target category:', error);
  }
  useStore.getState().setIsSettingsOpen(true);
};

